function withdrawals(){if(state.language==='zh')return `${shell('撤回与通知','冻结新的分发请求，计算影响范围并跟踪通知尝试。','<button class="button danger" data-action="new-withdrawal">发起撤回</button>')}<div class="metrics"><div class="metric"><span class="metric-label">进行中的撤回</span><strong>2</strong><small>其中 1 个通知正在重试</small></div><div class="metric"><span class="metric-label">受影响关系</span><strong>14</strong><small>消费者和组织引用</small></div><div class="metric"><span class="metric-label">已发送通知</span><strong>11</strong><small>送达不等于用户处置</small></div><div class="metric"><span class="metric-label">未知结果</span><strong>1</strong><small>等待接收方结果</small></div></div><section class="panel"><div class="panel-head"><h2>撤回事项</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>事项</th><th>Listing</th><th>来源</th><th>分发</th><th>通知</th><th>下一步</th></tr></thead><tbody><tr><td><strong>WD-018</strong><br/>今天生效</td><td>代码仓库治理工具包 v1.7.2</td><td>Owner 请求</td><td>${zhStatusTag('blocked','blocked')}<br/><small>已冻结</small></td><td>${zhStatusTag('failed','failed')}<br/><small>重试 2/5</small></td><td><button class="button" data-action="toast">重试通知</button></td></tr><tr><td><strong>WD-017</strong><br/>昨天完成</td><td>旧版流程启动包 v0.4.0</td><td>Governance ref</td><td>${zhStatusTag('blocked','blocked')}<br/><small>已冻结</small></td><td>${zhStatusTag('succeeded','succeeded')}<br/><small>已发送</small></td><td><button class="button" data-action="toast">查看影响</button></td></tr></tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>安全边界</h2></div><div class="panel-body"><div class="notice red">撤回生效后会冻结新的 Marketplace 分发，不会删除 owner 资产，也不证明已有安装已经停止。</div></div></section>`;return `${shell('Withdrawals & notifications','Freeze new distribution, calculate impact and track notification attempts.','<button class="button danger" data-action="new-withdrawal">Start withdrawal</button>')}<div class="metrics"><div class="metric"><span class="metric-label">Active withdrawals</span><strong>2</strong><small>one notification retrying</small></div><div class="metric"><span class="metric-label">Affected relations</span><strong>14</strong><small>consumer and organization refs</small></div><div class="metric"><div class="metric-label">Notifications delivered</div><strong>11</strong><small>delivery is not user disposition</small></div><div class="metric"><span class="metric-label">Unknown</span><strong>1</strong><small>receiver result pending</small></div></div><section class="panel"><div class="panel-head"><h2>Withdrawal cases</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Case</th><th>Listing</th><th>Source</th><th>Distribution</th><th>Notification</th><th>Next action</th></tr></thead><tbody><tr><td><strong>WD-018</strong><br/>Effective today</td><td>Repository hygiene toolkit v1.7.2</td><td>Owner request</td><td>${status('blocked','Frozen')}</td><td>${status('failed','Retry 2/5')}</td><td><button class="button" data-action="toast">Retry notice</button></td></tr><tr><td><strong>WD-017</strong><br/>Completed yesterday</td><td>Legacy process starter v0.4.0</td><td>Governance ref</td><td>${status('blocked','Frozen')}</td><td>${status('succeeded','Delivered')}</td><td><button class="button" data-action="toast">View impact</button></td></tr></tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Safety boundary</h2></div><div class="panel-body"><div class="notice red">Effective withdrawal freezes new Marketplace distribution. It does not delete the owner asset or prove that existing installations have stopped.</div></div></section>`}
function operations(){if(state.language==='zh')return `${shell('运营与恢复','Marketplace 局部诊断、投影维护和阻塞事项。','<button class="button" data-action="toast">刷新信号</button>')}<div class="content-grid"><section class="panel"><div class="panel-head"><h2>阻塞和未知事项</h2></div><div class="panel-body"><div class="side-list"><div class="side-item"><div><strong>Owner 引用已过期</strong><small>代码仓库治理工具包 · 来源检查</small></div>${zhStatusTag('blocked','blocked')}<button class="button" data-action="toast">重试</button></div><div class="side-item"><div><strong>分发提交结果未知</strong><small>外部接收方 · 请求 D-8802</small></div>${zhStatusTag('unknown','unknown')}<button class="button" data-action="toast">对账</button></div><div class="side-item"><div><strong>通知发送失败</strong><small>撤回 WD-018 · 渠道交接</small></div>${zhStatusTag('failed','failed')}<button class="button" data-action="toast">重试</button></div></div></div></section><section class="panel"><div class="panel-head"><h2>投影健康度</h2></div><div class="panel-body stack"><div><div class="metric-label">目录投影</div><strong>当前 · 128 个 Listing</strong></div><div class="progress"><span style="width:96%"></span></div><div><div class="metric-label">Owner 引用检查</div><strong>124 个当前 · 4 个过期</strong></div><div class="progress"><span style="width:88%"></span></div><div><div class="metric-label">审计交接</div><strong>等待外部交接</strong></div>${status('pending','不宣称就绪')}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>恢复边界</h2></div><div class="panel-body"><div class="notice">维护任务可以重试、重建或对账 Marketplace 局部状态，但不能修复来源真相、制造 Governance approval，或在没有 owner 结果时关闭外部未知提交。</div></div></section>`;return `${shell('Operations & recovery','Marketplace-local diagnostics, projection maintenance and blocked work.','<button class="button" data-action="toast">Refresh signals</button>')}<div class="content-grid"><section class="panel"><div class="panel-head"><h2>Blocked and unknown work</h2></div><div class="panel-body"><div class="side-list"><div class="side-item"><div><strong>Owner reference stale</strong><small>Repository hygiene toolkit · source check</small></div>${status('blocked','Blocked')}<button class="button" data-action="toast">Retry</button></div><div class="side-item"><div><strong>Distribution commit unknown</strong><small>External receiver · request D-8802</small></div>${status('unknown','Unknown')}<button class="button" data-action="toast">Reconcile</button></div><div class="side-item"><div><strong>Notification failed</strong><small>Withdrawal WD-018 · channel handoff</small></div>${status('failed','Failed')}<button class="button" data-action="toast">Retry</button></div></div></div></section><section class="panel"><div class="panel-head"><h2>Projection health</h2></div><div class="panel-body stack"><div><div class="metric-label">Catalog projection</div><strong>Current · 128 listings</strong></div><div class="progress"><span style="width:96%"></span></div><div><div class="metric-label">Owner ref checks</div><strong>124 current · 4 stale</strong></div><div class="progress"><span style="width:88%"></span></div><div><div class="metric-label">Audit handoff</div><strong>Pending external handoff</strong></div>${status('pending','No readiness claim')}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Recovery boundary</h2></div><div class="panel-body"><div class="notice">Maintenance can retry, rebuild or reconcile Marketplace-local state. It cannot repair source truth, manufacture Governance approval, or close an external commit unknown without an owner result.</div></div></section>`}
function applicationForm(){if(state.language==='zh')return `${shell('新建发布申请','原型表单 · 不会创建真实提交。','<button class="button" data-action="applications">取消</button>')}<section class="panel"><div class="panel-head"><h2>资产引用录入</h2><span class="network-pill">原型 fixture</span></div><div class="panel-body"><div class="form-grid"><div class="field"><label>资产 Owner 引用</label><input class="input" value="method://delivery/evidence-led@2.4.1"/></div><div class="field"><label>资产类型</label><select class="select"><option>流程模板</option><option>MCP 工具</option><option>成员镜像</option></select></div><div class="field"><label>发布者关系</label><input class="input" value="identity://publisher/aris-collective"/></div><div class="field"><label>申请可见性</label><select class="select"><option>公开</option><option>受限</option><option>仅组织可见</option></select></div><div class="field full"><label>版本摘要</label><textarea class="input">带有明确评审和证据交接的受治理交付方法。</textarea></div><div class="field full"><label>材料引用</label><input class="input" value="artifact://materials/MP-203, scan://pending, signature://pending"/></div></div><div class="notice" style="margin-top:18px">提交只会创建浏览器内的待处理演示状态。Governance approval、签名、扫描和包所有权仍归外部 owner。</div><div class="actions" style="margin-top:18px"><button class="button" data-action="applications">保存演示草稿</button><button class="button primary" data-action="submit-fixture">提交演示申请</button></div></div></section>`;return `${shell('New release application','Fixture form · no real submission will be created.','<button class="button" data-action="applications">Cancel</button>')}<section class="panel"><div class="panel-head"><h2>Asset reference intake</h2><span class="network-pill">Prototype fixture</span></div><div class="panel-body"><div class="form-grid"><div class="field"><label>Asset owner ref</label><input class="input" value="method://delivery/evidence-led@2.4.1"/></div><div class="field"><label>Asset type</label><select class="select"><option>Process Template</option><option>MCP Tool</option><option>Member Image</option></select></div><div class="field"><label>Publisher relation</label><input class="input" value="identity://publisher/aris-collective"/></div><div class="field"><label>Requested visibility</label><select class="select"><option>Public</option><option>Restricted</option><option>Organization only</option></select></div><div class="field full"><label>Release summary</label><textarea class="input">A governed delivery method with explicit review and evidence handoff.</textarea></div><div class="field full"><label>Material references</label><input class="input" value="artifact://materials/MP-203, scan://pending, signature://pending"/></div></div><div class="notice" style="margin-top:18px">Submitting this fixture creates only an in-browser pending state. Governance approval, signature, scan and package ownership remain external.</div><div class="actions" style="margin-top:18px"><button class="button" data-action="applications">Save fixture draft</button><button class="button primary" data-action="submit-fixture">Submit fixture application</button></div></div></section>`}
function applyLanguage(){const dict=translations[state.language];document.documentElement.lang=state.language==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i18n]').forEach(el=>{if(dict[el.dataset.i18n])el.textContent=dict[el.dataset.i18n]});const toggle=document.getElementById('language-toggle');if(toggle)toggle.textContent=state.language==='en'?'中文':'English'}
function render(){
  let content;
  if(state.view==='catalog') content=catalog();
  else if(state.view==='detail') content=detail();
  else if(state.view==='applications') content=applications();
  else if(state.view==='releases') content=releases();
  else if(state.view==='withdrawals') content=withdrawals();
  else if(state.view==='operations') content=operations();
  else content=applicationForm();
  main.innerHTML=content;
  applyLanguage();
  document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>{
    const action=el.dataset.action;
    if(action==='catalog') state.view='catalog';
    else if(action==='detail'||action==='show-detail') state.view='detail';
    else if(action==='applications') state.view='applications';
    else if(action==='releases') state.view='releases';
    else if(action==='withdrawals') state.view='withdrawals';
    else if(action==='operations') state.view='operations';
    else if(action==='new-application') state.view='form';
    else if(action==='new-withdrawal'){toast('Fixture withdrawal created: notification plan pending');return}
    else if(action==='submit-fixture'){toast('Fixture submitted: Governance handoff pending');state.view='applications';return}
    else {toast('Fixture action recorded locally');return}
    syncNav();render();
  }));
}
function syncNav(){document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===state.view))}
function toast(message){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t)}t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
document.querySelectorAll('.nav-item').forEach(el=>el.addEventListener('click',()=>{state.view=el.dataset.view;syncNav();render()}));
document.getElementById('language-toggle').addEventListener('click',()=>{state.language=state.language==='en'?'zh':'en';applyLanguage();render()});
render();
